print("\n--- 15-year explicit horizon (2027-2041), terminal RONIC 20% judgment ---")
def extend(s,m,g,n=5):
    s=list(s); m=list(m)
    for _ in range(n): s.append(s[-1]*(1+g)); m.append(m[-1])
    return s,m
ext={'base':extend(*cases['base'],0.05),'bear':extend(*cases['bear'],0.035),'bull':extend(*cases['bull'],0.06)}
res2={}
for k,(s,m) in ext.items():
    r=run(s,m,0.09,0.03,0.20); res2[k]=r
    print(k, f"per share EUR {r['ps']:.0f} EV {r['ev']:.0f} TV share {r['tv_share']:.0%} implied terminal EV/EBIT {r['impl_ev_ebit']:.1f} 2041 sales {s[-1]:.0f} 15y CAGR {(s[-1]/44.5)**(1/15)-1:.1%}")
ev2=sum(p[k]*res2[k]['ps'] for k in p); print("EV/share (prob-weighted)", round(ev2))
b=res2['base']; print("bridge: PV explicit",round(b['pv'],1),"PV CV",round(b['pvcv'],1),"EV",round(b['ev'],1),"equity",round(b['ev']+NETCASH+MISTRAL,1))
print("WACC x g, base 15y:")
for w in [0.08,0.085,0.09,0.095,0.10]:
    print(w,[round(run(*ext['base'],w,g,0.20)['ps']) for g in [0.02,0.025,0.03,0.035]])
print("bull at 8% WACC", round(run(*ext['bull'],0.08,0.03,0.20)['ps']), "base at 8%", round(run(*ext['base'],0.08,0.03,0.20)['ps']))
# CAP sensitivity: base path, value vs horizon 10/15/20 years
s20,m20=extend(*cases['base'],0.05,10)
for h in [10,15,20]:
    print("horizon",h, round(run(s20[:h],m20[:h],0.09,0.03,0.09 if h==10 else 0.20)['ps']), "(RONIC=WACC at terminal):", round(run(s20[:h],m20[:h],0.09,0.03,0.09)['ps']))
# sales needed: what 2030 sales at 46% margin and 15y horizon reproduce price? scale base path
for f in [1.2,1.4,1.6,1.8]:
    s=[x*f for x in ext['base'][0]]; print("scale",f,"2030 sales",round(s[3]),"per share",round(run(s,ext['base'][1],0.09,0.03,0.20)['ps']))
EOF
